                all(grid[r][c1] == color for r in range(r0,r1+1))):
            continue
        bitmap = [[grid[r][c] == color for c in range(c0+1,c1)]
                  for r in range(r0+1,r1)]
        boxes.append((color,r0,r1,c0,c1,bitmap))

    sources = [b for b in boxes if any(any(row) for row in b[5])]
    if len(sources) != 1:
        return grid
    src = sources[0]
    sh, sw = len(src[5]), len(src[5][0])
    out = [row[:] for row in grid]
    for color,r0,r1,c0,c1,bm in boxes:
        if color == src[0]:
            continue
        if len(bm) == sh and len(bm[0]) == sw:
            for dr in range(sh):
                for dc in range(sw):
                    if bm[dr][dc]:
                        out[r0+1+dr][c0+1+dc] = color
        else:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if out[r][c] == color:
                        out[r][c] = 0
    return out
