    boxes = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        # Identify the solid rectangular outline and read its interior as a bitmap.
        if (r1-r0 < 2 or c1-c0 < 2 or
            not all(grid[r0][c] == color for c in range(c0, c1+1)) or
            not all(grid[r1][c] == color for c in range(c0, c1+1)) or
            not all(grid[r][c0] == color for r in range(r0, r1+1)) or
            not all(grid[r][c1] == color for r in range(r0, r1+1))):
            continue
        inner = [[grid[r][c] == color for c in range(c0+1, c1)]
                 for r in range(r0+1, r1)]
        count = sum(sum(row) for row in inner)
        boxes.append((color, r0, r1, c0, c1, inner, count))

    patterned = [b for b in boxes if b[6] > 0]
    if not patterned:
        return [row[:] for row in grid]
    # The denser interior is the design; smaller stray designs are discarded.
    src = max(patterned, key=lambda b: b[6])
    pattern = src[5]
    ph, pw = len(pattern), len(pattern[0])
    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1, inner, count in boxes:
        # Preserve the source frame and its original motif. Empty frames receive
        # a top-left-aligned, clipped copy of that motif in their own color.
        for c in range(c0, c1+1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1+1):
            out[r][c0] = color
            out[r][c1] = color
        if (color, r0, r1, c0, c1) == (src[0], src[1], src[2], src[3], src[4]):
            for dr in range(ph):
